const sheetData = $json.values;
if (!sheetData || sheetData.length < 2) return [];
const headers = sheetData[0];
const results = [];
for (let i = 1; i < sheetData.length; i++) {
  const row = sheetData[i];
  if (!row || row.length === 0) continue;
  const obj = {};
  headers.forEach((header, idx) => { obj[header] = row[idx] !== undefined ? row[idx] : ''; });
  results.push({ json: obj });
}
return results;

// MODO DIAGNOSTICO: retorna TODOS os itens com campo 'diagnostico'
// para ver na aba Table o que esta acontecendo com cada linha.
// Apos confirmar que os dados estao corretos, troque DIAGNOSTICO para false.
const DIAGNOSTICO = false;

const MAPA_EMAILS = {
  'Rodrigo Bertolini': 'rodrigo.bertolini@fazcapital.com.br',
  'Lucas Boeira':      'lucas.boeira@fazcapital.com.br',
  'Allini Pianca':     'allini.pianca@fazcapital.com.br',
  'Athos Baruk':       'athos.baruk@fazcapital.com.br',
  'Fabio Borges':      'fabio.borges@fazcapital.com.br'
};

function findEmail(nome) {
  if (!nome) return '';
  if (MAPA_EMAILS[nome]) return MAPA_EMAILS[nome];
  const nomeLower = nome.toLowerCase();
  for (const [chave, email] of Object.entries(MAPA_EMAILS)) {
    const chaveLower = chave.toLowerCase();
    if (chaveLower.includes(nomeLower)) return email;
    if (chave.split(' ').some(p => p.toLowerCase() === nomeLower)) return email;
  }
  return '';
}

function norm(s) {
  return (s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
}

const d = $json;

// Mostra TODOS os nomes de colunas encontrados para diagnostico
const todasColunas = Object.keys(d).join(' | ');

// Suporte a variacoes de nome das colunas
const threadId  = (d['ID da thread'] || d['Thread ID'] || '').trim();
const status    = (d['Status'] || '').trim();
const ultStatus = (d['Último Status Enviado'] || d['Ultimo Status Enviado'] || '').trim();
const sNorm     = norm(status);
const uNorm     = norm(ultStatus);

const responsavel = (d['Responsável'] || d['Responsavel'] || '').split('|')[0].trim();
const emailDest   = findEmail(responsavel);

// Determina motivo do skip
let skipMotivo = 'OK - passaria';
if (!threadId)                         skipMotivo = 'SKIP: sem thread ID';
else if (sNorm === '' || sNorm === 'aberto') skipMotivo = 'SKIP: status vazio ou Aberto [' + status + ']';
else if (sNorm === uNorm)              skipMotivo = 'SKIP: status nao mudou [' + status + ']';
else if (!emailDest)                   skipMotivo = 'SKIP: responsavel nao encontrado [' + responsavel + ']';

if (DIAGNOSTICO) {
  // Em modo diagnostico: retorna tudo sem filtrar para inspecao
  return [{
    json: {
      diagnostico: skipMotivo,
      colunas_encontradas: todasColunas,
      _threadId: threadId,
      _status: status,
      _ultStatus: ultStatus,
      _responsavel: responsavel,
      _emailDest: emailDest,
      ...d
    }
  }];
}

// Modo normal: filtra e processa
if (skipMotivo !== 'OK - passaria') {
  return [];
}

const prompt =
  'Você é um assistente de suporte ao cliente profissional da FAZ Capital.\n' +
  'Transforme a nota de status abaixo em um parágrafo de e-mail formal, em português do Brasil.\n\n' +
  'Regras:\n' +
  '- Se houver texto entre aspas ("), reescreva esse conteúdo de forma profissional e elaborada em terceira pessoa\n' +
  '- Se for uma solicitação ou pedido (ex: aguardando..., precisa...), reformule de forma cordial e clara\n' +
  '- Não invente informações - apenas reformule o que foi fornecido\n' +
  '- Seja conciso, direto e profissional\n' +
  '- NAO inclua saudacao (Prezado(a)), assinatura nem qualquer outro elemento alem do paragrafo\n\n' +
  'Nota de status: "' + status + '"';

return [{
  json: {
    ...d,
    thread_id_ref: threadId,
    email_destinatario: emailDest,
    openai_body: {
      model: 'gpt-4o-mini',
      max_tokens: 400,
      messages: [{ role: 'user', content: prompt }]
    }
  }
}];

const textoAI = (
  $json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content
) || '';

if (!textoAI) {
  console.log('AVISO: IA nao retornou texto. Resposta:', JSON.stringify($json));
  return [];
}

const d         = $('PREPARAR_PROMPT_IA').item.json;
const idCaso    = d['ID Caso']            || '';
const cliente   = d['Código Cliente']     || d['Codigo_Cliente'] || '';
const assunto   = d['Assunto']             || '';
const proto     = d['Protocolo N1']        || '';
const status    = (d['Status'] || '').trim();
const threadId  = d['thread_id_ref']      || '';
const emailDest = d['email_destinatario'] || '';

if (!emailDest || !threadId) {
  console.log('SKIP: emailDest ou threadId ausente');
  return [];
}

const subjectLine = 'Re: [SUBIR BV] ' + idCaso + ' | Cliente ' + cliente + ' | ' + assunto;

const corpo =
  'Prezado(a),\n\n' +
  textoAI + '\n\n' +
  'Status: ' + status + '\n\n' +
  '📌 Protocolo: ' + proto + '\n' +
  '👤 Cliente: ' + cliente + '\n\n' +
  '📝 Assunto Caso: ' + assunto + '\n\n' +
  '\n\nAtenciosamente,\n\n';

console.log('OK: e-mail montado para', emailDest, '| Status:', status);

return [{
  json: {
    ...d,
    corpo_email: corpo,
    assunto_email: subjectLine,
    request_body: {
      message: {
        subject: subjectLine,
        body: { contentType: 'Text', content: corpo },
        toRecipients: [{ emailAddress: { address: emailDest } }],
        ccRecipients:  [{ emailAddress: { address: 'lucas.boeira@fazcapital.com.br' } }],
        internetMessageHeaders: [
          { name: 'In-Reply-To', value: threadId },
          { name: 'References',  value: threadId }
        ]
      }
    }
  }
}];
